/*
 * Statistics container
 *
 * (c) 2014 Hannes Christiansen, http://www.runalyze.de/
 */
Runalyze.Statistics = (function($, Parent){

	// Public

	var self = {};


	// Private

	var options = {
		selectorMenu:		'#statistics-nav',
		selectorMenuItems:	'#statistics-nav li',
		selectorContent:	'#statistics-inner',
		activeClass:		'active',
		urlStat:			'my/plugin/'
	};

	var $menu;
	var $menuItems;
	var $content;

	var currentUrl;


	// Private Methods

	function initObjects() {
		$menu = $( options.selectorMenu );
		$menuItems = $( options.selectorMenuItems );
		$content = $( options.selectorContent );

		if (!Parent.isReady()) {
			self.resetUrl();
		} else {
			$menuItems.removeClass( options.activeClass );
			$menuItems.children("a[href='"+self.currentTabContentUrl+"']").parent().addClass("active");
		}
	}

	function bindLinks() {
		$menuItems.unbind('click').click(function(e) {
			e.preventDefault();

			Parent.Training.removeHighlighting();
			$menuItems.removeClass( options.activeClass );

			$(this).addClass( options.activeClass );

			self.load( $(this).find('a').attr('href') );

			return false;
		});
	}


	// Public Methods

	self.init = function() {
		initObjects();
		bindLinks();
	};

	self.currentUrl = function() {
		return currentUrl;
	};

	self.setUrl = function(url) {
		currentUrl = url;
	};

	self.resetUrl = function() {
		currentUrl = $( options.selectorMenuItems + ':first a' ).attr('href');
	};

	self.showsTraining = function() {
		return Parent.Training.isUrl( currentUrl );
	};

	self.shows = function(id) {
		return (currentUrl == options.urlStat + id.toString()) || (currentUrl.lastIndexOf( options.urlStat + id.toString() + '?', 0 ) === 0);
	};

	self.currentId = function() {
		if (self.showsTraining())
			return currentUrl.substr( Parent.Training.url('').length );

		return currentUrl.substr(options.urlStat.length).split('?', 1)[0];
	};

	self.reload = function() {
		if (currentUrl != '') {
			var $link = $menuItems.children("a[href='"+self.currentTabContentUrl+"']");

			if ($link.length) {
				Parent.Training.removeHighlighting();

				$menuItems.removeClass( options.activeClass );
				$link.addClass( options.activeClass );
			}

			self.load( currentUrl );
		}
	};

	self.load = function(url) {
		$content.loadDiv( url );
		currentUrl = url.replace('app_dev.php/', '');
	};

	self.loadTraining = function(url) {
		$menuItems.removeClass( options.activeClass );

		self.load(url);
	};

	Parent.addInitHook('init-statistics', self.init);

	return self;
})(jQuery, Runalyze);

;
// ---- lib/runalyze.lib.training.js ----
/*
 * Training
 *
 * (c) 2014 Hannes Christiansen, http://www.runalyze.de/
 */
Runalyze.Training = (function($, Parent){

	// Public

	var self = {};


	// Private

	var options = {
		url:				'activity/',
		urlSaveTCX:			'_internal/upload/tcx',
		highlightClass:		'highlight'
	};


	// Private Methods


	// Public Methods

	self.initLinks = function() {
		$("a.training").unbind("click").click(function(e){
			e.preventDefault();
			self.load($(this).attr("rel"));
			return false;
		});
	};

	self.load = function(id, sharedUrl, event) {
		if (event) {
			event.stopPropagation();
		}

		var $w = $(window);
		var $inner = $("#statistics-inner");
		var $stats = $("#statistics");

		if ($inner.length && $w.scrollTop() + $w.height() < $inner.offset().top) {
			$('html, body').stop().animate({
				scrollTop: ($stats.length ? $stats : $inner).offset().top - 43
			}, 1000);
		}

		Parent.Statistics.load( sharedUrl || self.url(id) );

		self.removeHighlighting();
		self.addHighlighting(id);
	};

	self.reload = function() {
		if (Parent.Statistics.showsTraining())
			Parent.Statistics.reload();
	};

	self.isUrl = function(urlToCheck) {
		return (urlToCheck.lastIndexOf( options.url, 0 ) === 0);
	};

	self.url = function(id) {
		return options.url + id.toString();
	};

	self.removeHighlighting = function() {
		$("#data-browser").find("tr.training").removeClass( options.highlightClass );
	};

	self.addHighlighting = function(id) {
		$("#training_"+id).addClass( options.highlightClass );
	};

	self.saveTcx = function(xml, activityId, index, total, activities) {
		$.post(options.urlSaveTCX, {'activityId': activityId, 'data': xml}, function(){
			if (index == total) {
				self.loadSavedTcxs(activities);
			}
		});
	};

	self.loadSavedTcxs = function(activityIds) {
		Parent.Overlay.container().loadDiv($("form#training").attr("action"), {'activityIds': activityIds, 'data': 'FINISHED'});
	};

	self.loadXML = function(xml) {
		Parent.Overlay.container().loadDiv($("form#training").attr("action"), {'data': xml});
	};

	self.deleteActivity = function(id, confirmMsg, settings) {
		if (confirmMsg) {
			if (!window.confirm(confirmMsg)) {
				return false;
			}
		}

		settings = $.extend({}, {size:'small', useOverlay: false}, settings);

		if (settings.useOverlay) {
			Parent.Overlay.load(
				Parent.Training.url(id) + "?action=delete",
				settings
			);

			return false;
		}

		$.ajax(self.url(id) + "?action=delete", settings);
	};


	self.changePrivacyOfActivity = function(id, settings) {
		$.ajax(self.url(id) + "?action=changePrivacy&silent=true", settings);
	};

	Parent.addLoadHook('init-training-links', self.initLinks);

	return self;
})(jQuery, Runalyze);

;
// ---- lib/runalyze.lib.activity.form.js ----
Runalyze.ActivityForm = (function($, Common, Formatter){

	// Public

	var self = {};

	// Private

	var form = null;
    var splits = null;
    var weather = null;
    var equipment = null;
    var defaultSplit = '';
    var caloriesPerHour = 0;
    var currentPaceUnit = 0;

    var options = {
        baseId: 'activity',
        isNew: true,
        calculateCalories: true,
        canLoadWeather: true,
        loadWeather: true
    };

    var weatherSourceLabels = {
        darksky: 'Dark Sky',
        openweathermap: 'OpenWeatherMap',
        meteostatnet: 'meteostat.net'
    };
    var weatherReasonLabels = {
        not_possible: 'not configured on this server',
        no_data: 'no data available for this location/time',
        auth_failed: 'request rejected (check API configuration/credentials)',
        rate_limited: 'query limit exceeded',
        request_failed: 'no response received (network error)',
        too_old: 'only provides current conditions; this activity is too old for that'
    };

	// Private Methods
    function isNewActivity() {
        return options.isNew;
    }

    function isWeatherEmpty() {
        var isConditionUnknown = '1' === findId('weatherid', weather).val();
        var inputsAreEmpty = weather.find('input').length === weather.find('input').filter(function(){return $.trim($(this).val()).length === 0;}).length;

        return isConditionUnknown && inputsAreEmpty;
    }

    function find(selector, baseElement) {
        return (baseElement || form).find(selector);
    }

    function findInput(name, baseElement) {
        return find('input[name="' + options.baseId + '[' + name + ']"]', baseElement);
    }

    function findId(name, baseElement) {
        return $('#' + options.baseId + '_' + name);
    }

    function initialUpdates() {
        var emptyType = findId('type').find('option[value=""]');
        emptyType.text('---- ' + emptyType.text());

        initLayoutForEquipment();
        updateRaceDependentVisibilities();
        updateAvailableEquipmentWithRespectToDate();
        updateVisibilitiesAndDefaultValuesForSport(findId('sport').find(':selected:first'), true);

        updatePace();

        if (!(parseInt(findInput('kcal').val()) > 0)) {
            updateCalories();
        }

        if (isWeatherEmpty()) {
            if (isNewActivity() && options.canLoadWeather && options.loadWeather) {
                tryToLoadWeatherData();
            } else {
                hideAndUnsetWeatherInputs();
            }
        } else {
            var sources = ['', 'openweathermap.org', '', 'Powered by Dark Sky'];
            var source = sources[findId('weatherSource').val()];

            if (source) {
                weather.find('.weatherdata-source').html('via ' + source);
            }
        }

        hideSelectedDataSeriesAfterSubmit();
    }

    function initHandlers() {
        initChangeSportHandler();
        initChangeDateHandler();
        initChangeRaceHandler();
        initChangeDistanceOrDurationHandler();
        initSplitsHandlers();
        initSingleSplitHandlers();
        initWeatherHandlers();
    }

    function initChangeSportHandler() {
        findId('sport').change(function() {
            updateVisibilitiesAndDefaultValuesForSport($(this).find(':selected:first'));

            if (options.calculateCalories) {
                updateCalories();
            }

            updatePace();
        });
    }

    function initChangeDateHandler() {
        findId('time_date').change(function(){
            updateAvailableEquipmentWithRespectToDate();

            if (options.loadWeather && findInput('weatherSource').val().length > 0) {
                tryToLoadWeatherData(false);
            }
        });
    }

    function initChangeRaceHandler() {
        findId('is_race').change(function(){
            updateRaceDependentVisibilities($(this).prop('checked'));
        });
    }

    function initChangeDistanceOrDurationHandler() {
        form.find('#' + options.baseId + '_distance, #' + options.baseId + '_s').change(function() {
            updatePace();

            if (options.calculateCalories) {
                updateCalories();
            }
        });
    }

    function initSplitsHandlers() {
        splits.find('.add-split').click(function(){
            splits.find('.splits').append(defaultSplit);
            var newSplit = splits.find('.splits li:last');
            newSplit.find('.split-distance input').val('1.00');
            newSplit.find('.split-duration input').val('6:00');
            newSplit.find('.split-intensity select').val('');

            reIndexSplits();
            initSingleSplitHandlers();
        });

        splits.find('.round-splits').click(function(){
            splits.find('.splits .split-distance input').each(function(e){
                $(this).val((Math.round(10 * $(this).val()) / 10).toFixed(2));
            });
        });

        splits.find('.sum-splits').click(function(){
            var dist = 0, time = 0;

            splits.find('.splits .split-distance input').each(function(e){
                dist += stringToDistance($(this).val());
            });
            splits.find('.splits .split-duration input').each(function(e){
                time += Common.stringToSeconds($(this).val());
            });

            findId('s').val(Common.secondsToString(time));
            findId('distance').val(dist.toFixed(2));

            updatePace();
        });

        splits.find(".active-splits").click(function(){
            splits.find('.splits .split-intensity select').val('');
        });

        splits.find(".rest-splits").click(function(){
            splits.find('.splits .split-intensity select').val('R');
        });

        var evenSplits = function(val) {
            splits.find('.splits .split-intensity:even select').val(val);
        };

        var oddSplits = function(val) {
            splits.find('.splits .split-intensity:odd select').val(val);
        };

        splits.find(".alternate-splits-rest").click(function(){
            evenSplits('R');
            oddSplits('');
        });

        splits.find(".alternate-splits-active").click(function(){
            evenSplits('');
            oddSplits('R');
        });
    }

    function initSingleSplitHandlers() {
        splits.find(".split-copy").unbind('click').click(function(){
            var $p = $(this).parent();
            $p.clone().insertAfter($p);

            reIndexSplits();
            initSingleSplitHandlers();
        });

        splits.find(".split-remove").unbind('click').click(function(){
            $(this).parent().remove();

            reIndexSplits();
            initSingleSplitHandlers();
        });
    }

    function reIndexSplits() {
        var nameByIndex = function(field, index) {
            return options.baseId + '[splits][' + index + '][' + field + ']';
        };
        var idByIndex = function(field, index) {
            return nameByIndex(field, index).replace(/\[/g, '_').replace(/\]/g, '');
        };

        var index = 0;

        splits.find("li").each(function(){
            $(this).find('.split-distance input').attr('id', idByIndex('distance', index)).attr('name', nameByIndex('distance', index));
            $(this).find('.split-distance label').attr('for', idByIndex('distance', index));
            $(this).find('.split-duration input').attr('id', idByIndex('duration', index)).attr('name', nameByIndex('duration', index));
            $(this).find('.split-intensity select').attr('id', idByIndex('isActive', index)).attr('name', nameByIndex('isActive', index));

            ++index;
        });
    }

    function initWeatherHandlers() {
        weather.find('.weatherdata-button-load').click(function(){
            tryToLoadWeatherData();
        });

        weather.find('.weatherdata-button-edit').click(function() {
            weather.find('.w50, .weatherdata-source, .weatherdata-button-remove').removeClass('hide');
            weather.find('.weatherdata-none-text, .weatherdata-button-edit').addClass('hide');
        });

        weather.find('.weatherdata-button-remove').click(function(){
            hideAndUnsetWeatherInputs();
        });
    }

    function updateVisibilitiesAndDefaultValuesForSport(elem, initial) {
        var sportId = elem.val(),
            elemType = findId('type'),
            kcal = parseInt(elem.data('energy')) || false,
            internal = parseInt(elem.data('internal')) || false,
            equipmentTypes = elem.data('equipment-types');

        if (kcal > 0)
            caloriesPerHour = kcal;

        currentPaceUnit = elem.data('speed');

        form.find('.only-running').toggle(internal === 1);
        form.find('.only-not-running').toggle(internal !== 1);
        form.find('.only-power').toggle(elem.data('power') === 1);
        form.find('.only-outside').toggle(elem.data('outside') === 1);
        form.find('.only-distances').toggle(elem.data('distances') === 1);

        elemType.find('option:not([value=""])').attr('disabled', true).hide();
        elemType.find('option[data-sport=' + sportId + ']').attr('disabled', false).show();
        $('.only-specific-sports:not(.only-sport-' + sportId + ')').attr('disabled', true).hide();
        $('.only-specific-sports.only-sport-' + sportId).attr('disabled', false).show();

        if (elemType.find('option:selected').attr('disabled')) {
            elemType.find('option:selected').attr('selected', false);
            elemType.find('option[data-sport=all]').attr('selected', false);
        }

        if (!initial) {
            findId('is_public').prop('checked', !parseInt(elem.data('privacy')));
        }

        elemType.parent().toggle(elemType.find('option[value!=""]:not(:disabled)').length > 0);

        updateDefaultType(elemType, elem.attr('data-activity-type'));

        if (equipmentTypes.length) {
            equipment.find('#' + options.baseId + '_equipment > div').hide();

            equipmentTypes.forEach(function (id) {
                equipment.find('#' + options.baseId + '_equipment_' + id).parent().show();
            });

            equipment.show();
        } else {
            equipment.hide();
        }
    }

    function updateDefaultType(elemType, defaultId) {
        if (options.isNew) {
            elemType.find('option:selected').attr('selected', false);
            elemType.find('option[value="' + defaultId + '"]').prop('selected', true);
        }
    }

    function initLayoutForEquipment() {
        equipment.find('.depends-on-date > label').hide();
        equipment.find('.w100').addClass('with50erLabel');
        equipment.find('select').addClass('full-size');
        equipment.find('.w100 > div').each(function() {
            $(this).addClass('full-size left checkbox-collection');
            var id = $(this).attr('id');
            $(this).find('label').each(function(i) {
                $(this).addClass(id + '-' + i);
            });
            $(this).find('input').each(function(i) {
                $(this).addClass(id + '-' + i);
                equipment.find('.' + id + '-' + i).wrapAll('<div class="inline small w25" />');
            });
        });
    }

    function updateAvailableEquipmentWithRespectToDate() {
        var date = Common.parseDate(findId('time_date').val(), 'yyyy-mm-dd').getTime();

        form.find('.depends-on-date option, .depends-on-date input').each(function(){
            var available = date == 0 || (
                    !($(this).data('start') && Common.parseDate($(this).data('start')) > date) &&
                    !($(this).data('end') && Common.parseDate($(this).data('end')) < date)
                );

            $(this).attr('disabled', !available).toggle(available);
            $(this).attr('hidden', !available).toggle(available);

            if (!$(this).is('option')) {
                $(this).parent().toggle(available);
            }

            if (!available) {
                if ($(this).is('option')) {
                    $(this).prop('selected', false);
                } else {
                    $(this).prop('checked', false);
                }
            }
        });
    }

    function updateCalories() {
        findId('kcal').val(Math.round(Number(caloriesPerHour) * getTimeInHours()));
    }

    function updatePace() {
        var d = getDistance(),
            s = getTimeInSeconds(),
            elem = findId('pace');

        var paceObject = Formatter.getPaceObject(d > 0.0 ? s / d : 0.0, currentPaceUnit);

        elem.val(paceObject.string);
        elem.next().text(paceObject.shortAppendix);
    }

    function updateWeatherDataFrom(data) {
        if (data && !data.empty) {
            var locationDetails = [];

            if (data.location) {
                if (data.location.name) {
                    locationDetails.push(data.location.name);
                } else if (data.location.lat && data.location.lng) {
                    locationDetails.push(Math.abs(data.location.lat).toFixed(2) + ' °' + (data.location.lat >= 0 ? 'N' : 'S') + ', ' + Math.abs(data.location.lng).toFixed(2) + ' °' + (data.location.lng >= 0 ? 'W' : 'E'));
                }

                if (data.location.date && !isNaN(Date.parse(data.location.date))) {
                    locationDetails.push((new Date(data.location.date)).toLocaleString());
                }
            }

            findId('weatherid', weather).val('' + data.weatherid);
            findId('temperature', weather).val(Math.round('1' == findId('temperature', weather).data('is-fahrenheit') ? data.temperature * 1.8 + 32.0 : data.temperature));
            findId('wind_speed', weather).val(Math.round(data.wind_speed / findId('wind_speed', weather).data('base-unit-factor')));
            findId('wind_deg', weather).val(data.wind_deg);
            findId('humidity', weather).val(data.humidity);
            findId('pressure', weather).val(data.pressure);
            weather.find('.weatherdata-source').html('via ' + data.source.name + (locationDetails.length > 0 ? ' (' + locationDetails.join(', ') + ')' : ''));
            findId('weatherSource', weather).val(data.source.id);
        }
    }

    function updateRaceDependentVisibilities(val) {
        if (typeof val === "undefined") {
            val = findId('is_race').prop('checked');
        }

        form.find('.only-race').toggle(val);
    }
    function buildWeatherDiagnosticsHtml(sources) {
        if (!sources || !sources.length) {
            return null;
        }

        var items = sources.map(function(entry) {
            var sourceLabel = weatherSourceLabels[entry.source] || entry.source;
            var reasonLabel = weatherReasonLabels[entry.reason] || entry.reason;

            return '<li><strong>' + sourceLabel + '</strong>: ' + reasonLabel + '</li>';
        });

        return '<ul class="weatherdata-diagnostics">' + items.join('') + '</ul>';
    }

    function tryToLoadWeatherData(hideIfRequestFails) {
        hideIfRequestFails = hideIfRequestFails || true;

        weather.find('.weatherdata-loading-text').removeClass('hide');
        weather.find('.weatherdata-none-text').addClass('hide');

        var args = [];

        // #TSC build a date with date+time to an object with format 'yyyy-mm-ddThh:mm:ss'
        // new is to use the time from the form in the date
        var date = new Date(findId('time_date').val() + 'T' + findId('time_time').val() + ':00');
        if(isNaN(date)) {
            // if the input was wrong use current date
            date = new Date();
        } else {
            // add the duration to the date # TSC
            date = addMinutes(date, findId('s').val());
        }
        // now we have a date with the time in the half of our activity -> ideal to get this weather

        // build the parameters for the internal API call
        args.push('date=' + date.getFullYear() + '-' + (date.getMonth() + 1) + '-' + date.getDate() + 'T' + date.getHours() + ':' + date.getMinutes())

        var startCoords = findId('start-coordinates').val();

        if (startCoords && startCoords.length) {
            args.push('latlng=' + startCoords);
        }

        $.get('_internal/service/weather?'+args.join('&'), function(data) {
            if (!data.empty) {
                updateWeatherDataFrom(data);

                weather.find('.weatherdata-none-text, .weatherdata-button-edit, .weatherdata-loading-text').addClass('hide');
                weather.find('.w50, .weatherdata-source, .weatherdata-button-remove').removeClass('hide');
            } else {
                weather.find('.weatherdata-loading-text').addClass('hide');

                var diagnosticsHtml = buildWeatherDiagnosticsHtml(data.sources);
                if (diagnosticsHtml) {
                    weather.find('.weatherdata-none-text').html(diagnosticsHtml);
                }

                if (hideIfRequestFails) {
                    weather.find('.weatherdata-none-text, .weatherdata-button-edit').removeClass('hide');
                    weather.find('.w50, .weatherdata-source, .weatherdata-button-remove').addClass('hide');
                }
            }
        }).fail(function(){
            weather.find('.weatherdata-loading-text').addClass('hide');

            if (hideIfRequestFails) {
                weather.find('.weatherdata-none-text, .weatherdata-button-edit').removeClass('hide');
                weather.find('.w50, .weatherdata-source, .weatherdata-button-remove').addClass('hide');
            }
        });
    }

    /**
     * adds the hour+minutes of the duration to the date.
     * #TSC
     */ 
    function addMinutes(date, hhmmss) {
        // split the duration: format must be: [hh:]mm:ss
        elements = hhmmss.split(':')
        if(elements.length < 2 || elements.some(isNaN)) {
            return date;
        }

        // we have hh:mm:ss, so purge the ss=seconds; seconds not needed
        elements.pop();

        // now calculate from hh and mm the minutes of the duration
        // the loop iterates the reverse order (from minutes>hours) and increments the minutes
        // we do not use 60 (minutes) but 30 => we want the half duration
        min = 0;
        for(i = elements.length - 1, tt = 30 * 1000; i >= 0; i--, tt = tt * 60) {
            min = min + elements[i] * tt;
        };

        // add the minutes/2 to the incoming date
        return new Date(date.getTime() + min);
    }

    function hideAndUnsetWeatherInputs() {
        weather.find('.w50, .weatherdata-source, .weatherdata-button-remove').addClass('hide');
        weather.find('.weatherdata-none-text, .weatherdata-button-edit').removeClass('hide');

        findId('weatherid', weather).val('1');
        weather.find('input').val('');
        weather.find(".weatherdata-source").html('');
    }

    function hideSelectedDataSeriesAfterSubmit() {
        $("#fieldset-remove-data-series").find("input:checked").each(function(){
            $(this).parent().hide();
        });
    }

    function getDistance() {
        return stringToDistance(findId('distance').val());
    }

    function getTimeInHours() {
        return (getTimeInSeconds() / 3600);
    }

    function getTimeInSeconds() {
        return Common.stringToSeconds(findId('s').val());
    }

    function stringToDistance(string) {
        return Number(string.replace(',', '.')) * form.find('input[name=distance-to-km-factor]').val();
    }

	// Public Methods

    self.setOptions = function(opt) {
        options = $.extend({}, options, opt);
    };

	self.init = function(elem, opt) {
	    form = elem;
        splits = elem.find('#fieldset-splits');
        weather = elem.find('#fieldset-weather');
        equipment = elem.find('#fieldset-equipment');
        defaultSplit = '<li>' + splits.find('.split-prototype').html() + '</li>';
        splits.find('.split-prototype').remove();

        self.setOptions(opt);

        options.canLoadWeather = weather.find('.weatherdata-button-load').length > 0;

        initHandlers();
        initialUpdates();
	};

	return self;
})(jQuery, Runalyze.Common, Runalyze.Formatter);

;
// ---- lib/runalyze.lib.feature.js ----
/*
 * Feature
 *
 * (c) 2014 Hannes Christiansen, http://www.runalyze.de/
 */
Runalyze.Feature = (function($, Parent){

	// Public

	var self = {};


	// Private

	var options = {
	};


	// Private Methods

	function initAjaxLinks() {
		$('a.ajax').unbind('click').click(function(e){
			e.preventDefault();

			if ($(this).data('confirm')) {
				if (!window.confirm($(this).data('confirm'))) {
					return false;
				}
			}

			var href = $(this).attr('href');
			var target = $(this).attr('target');

			if (href != '#') {
				if (target == 'statistics-inner') {
					Parent.Statistics.setUrl( href );
				}

				$('#'+target).loadDiv(href, $(this).attr("data-size"));
			}

			return false;
		});
	}

	function initTooltips() {
		$("body > .tooltip").remove();
		$("[rel=tooltip].atLeft").tooltip({animation: true, placement: 'left'});
		$("[rel=tooltip].atRight").tooltip({animation: true, placement: 'right'});
		$("[rel=tooltip]:not(.atLeft):not(.atRight)").tooltip({animation: true});

		return this;
	}

	function initToggle() {
		$(".toggle").unbind("click").click(function(e){
			e.preventDefault();
			$("#"+$(this).attr("rel")).animate({opacity: 'toggle'});
		});
	}

	function initToolbars() {
		$(".toolbar-opener").unbind("click").click(function(){
			$(this).parent().parent().toggleClass('open');
		});
	}

	function initChangeDiv() {
		$("a.change").each(function(){
			if ($("a.change[target="+$(this).attr("target")+"].triggered").length == 0)
				$("a.change[target="+$(this).attr("target")+"]:first").addClass('triggered').parent().addClass('triggered');
			else
				$("a.change[target="+$(this).attr("target")+"].triggered").parent().addClass('triggered');
		}).unbind("click").click(function(e){
			e.preventDefault();

			$(this).closest("li.with-submenu").find("span.link").text($(this).text());

			$("a.change[target="+$(this).attr("target")+"]").removeClass('triggered').parent().removeClass('triggered');
			$(this).addClass('triggered').parent().addClass('triggered');

			var target = "#"+$(this).attr("target");
			var $target = $(target);

			if (target == $(this).attr("href")) {
				var $newDiv = $("#"+ $(this).attr("href").split('#').pop() + " .change");
			} else {
				var $newDiv = $("#"+ $(this).attr("href").split('#').pop());
			}

			var $oldDiv = $(target+" > .change:visible, " + target + " > .panel-content > .change:visible, " + target + " > .statistics-container > .change:visible").not($newDiv);

			$target.addClass('loading');

			var fadeInNewDiv = function() {
				$newDiv.fadeTo( Parent.Options.fadeSpeed(), 1, function(){
					$target.hide().removeClass( Parent.Options.loadingClass() ).fadeIn();
					Parent.createFlot();
					RunalyzePlot.resizeAll();
				});
			};

			if ($oldDiv.length) {
				$oldDiv.fadeOut( Parent.Options.fadeSpeed(), fadeInNewDiv);
			} else {
				fadeInNewDiv();
			}

			return false;
		});
	}

	function initCalendarLink() {
		$('#calendar-link').unbind('click').bind('click', function(){
			var $e = $('#data-browser-calendar');

			$e.toggle();

			if ($e.is(':visible'))
				initCalendar();
		});
	}

	function initCalendar() {
		var $calendar = $('#widget-calendar');

		if ($calendar.text().trim().length > 0)
			return this;

		var dateStart = new Date(parseInt($("#calendar-start").val()));
		var dateEnd = new Date(parseInt($("#calendar-end").val()));

		$calendar.DatePicker({
			flat: true,
			format: 'd B Y',
			date: [new Date(dateStart.getTime() + dateStart.getTimezoneOffset()*60000), new Date(dateEnd.getTime() + dateEnd.getTimezoneOffset()*60000)],
			current: new Date(dateStart.getTime() + dateStart.getTimezoneOffset()*60000),
            locale:  JSON.parse($("#calendar-locale").val()),
			calendars: 3,
            mode: 'range',
			starts: 1
		});

		$('#calendar-submit').unbind('click').bind('click', function(){
			var dates = $calendar.DatePickerGetDate(),
				start = Math.round(dates[0].getTime()/1000 - dates[0].getTimezoneOffset()*60),
				end = Math.round(dates[1].getTime()/1000 - dates[1].getTimezoneOffset()*60);
			$("#data-browser-inner").loadDiv('call/call.DataBrowser.display.php?start='+start+'&end='+end);
		});

		return this;
	}

	function initFormulars() {
		initFormularElements();
		initFormularSubmit();
	}

	function initFormularElements() {
		var config = {
			'.chosen-select-create': {width: "auto", create_option: true, skip_no_results: true, create_option_text:"Add a tag"},
			'.chosen-select': {width: "auto", no_results_text: "No results match"}
		};

		for (var selector in config) {
			$(selector).chosen(config[selector]);
		}

		$(".chosen-select-all").unbind('click').bind('click', function() {
			var target = $(this).data('target');
			$("#"+target+" option").prop('selected', true);
			$("#"+target).change().trigger('chosen:updated');
		});
		$(".chosen-select-none").unbind('click').bind('click', function() {
			var target = $(this).data('target');
			$("#"+target+" option").prop('selected', false);
			$("#"+target).change().trigger('chosen:updated');
		});

		$(".fip-select").fontIconPicker({emptyIcon: false, hasSearch: false});
		$(".pick-a-date:not(.has-a-datepicker)").each(function(){
			var $t = $(this);
			var $locale = $("#calendar-locale");
			var options = {
                format: $(this).data('format') || 'd.m.Y',
                date: $t.val(),
                current: $t.val(),
                calendars: 1,
                starts: 1,
                position: 'bottom',
                mode: 'single',
                onBeforeShow: function(){ if ($t.val().trim() != '') $t.DatePickerSetDate($t.val(), true); },
                onChange: function(formated, dates){ $t.val(formated); $t.trigger('change'); $t.DatePickerHide(); }
            };

			if ($locale && $locale.val()) {
				options.locale = JSON.parse($locale.val());
			}

            $t.addClass('has-a-datepicker');

			$t.DatePicker(options);
		});

		$('form label, form .checkbox-collection > div').each(function(){
			if (this.offsetWidth < this.scrollWidth) {
				$(this).attr('title', $(this).text().trim()).tooltip({animation: true});
			}
		});
	}

	function initFormularSubmit() {
		// Warning: Does only work for formulars in #ajax
		$("#ajax").find("form.ajax").unbind("submit").submit(function(e){
			e.preventDefault();

			if ($(this).children(":submit").hasClass('debug')) {
				window.alert($(this).serialize());
				return false;
			}

			if ($(this).data('confirm')) {
				if (!window.confirm($(this).data('confirm'))) {
					return false;
				}
			}

			var formID = $(this).attr("id");
			var noreload = $(this).hasClass('no-automatic-reload');
			var data = $(this).serializeArray();
			var url = $(this).attr('action');
			var elem = $("#ajax");

			data.push({
				name:	'submit',
				value:	'submit'
			});

			if (formID == "search" && $("form.ajax input[name=send-to-multi-editor]:checked").length == 0) {
				$("#searchResult").loadDiv(url+'?pager=true', data, {success: function(){
					$('#searchResult').find('.submenu .link').unbind('click').bind('click', function(){
						var element = $(this);
						if (element.data('action') == 'delete') {
							Parent.Training.deleteActivity(element.data('activityid'), element.data('confirm'), {
								success: function() {
									element.closest('tr').remove();
								}
							});
						} else if (element.data('action') == 'privacy') {
							Parent.Training.changePrivacyOfActivity(element.data('activityid'), {
								success: function() {
									$('#search').submit();
								}
							});
						}
					});
				}});
				return false;
			}

			$("body > .datepicker").remove();

			if ($("#pluginTool").length) {
				elem = $("#pluginTool");
			}

			elem.loadDiv( url, data, {
				success: function() {
					$("#submit-info").fadeIn().delay(4000).fadeOut();

					if (formID != "search" && formID != "tcxUpload" && !noreload)
						Parent.reloadContent();
				}
			} );

			return false;
		});
	}

	function initRelativeTimes() {
		$('time.timeago').timeago();
	}


	// Public Methods

	self.init = function() {
		initAjaxLinks();
		initTooltips();
		initToggle();
		initToolbars();
		initChangeDiv();
		initCalendarLink();
		initFormulars();
		initRelativeTimes();
	};

	self.initToggle = function() {
		initToggle();
	};

	self.radialProgress = function(element, scoreInPercent, scoreAsValue) {
        element.find('.inset').text(scoreAsValue.toFixed(1));

        var transform_styles = ['-webkit-transform', '-ms-transform', 'transform'];
        var mask = element.find('.fill, .mask.full');
        var fix = element.find('.fill.fix');

        for (var i in transform_styles) {
            mask.css(transform_styles[i], 'rotate(' + (scoreInPercent * 180) + 'deg)');
            fix.css(transform_styles[i], 'rotate(' + (scoreInPercent * 360) + 'deg)');
        }
	};

	Parent.addLoadHook('init-feature', self.init);

	return self;
})(jQuery, Runalyze);

;
// ---- lib/runalyze.lib.notifications.js ----
Runalyze.Notifications = (function($, Parent){

    // Public

    var self = {};

    // Private

    var options = {
        cronjobInterval: 60
    };

    var lastRequest = Math.floor(new Date().valueOf() / 1000);

    var urls = {
        markAllRead: '_internal/notifications/read/all',
        markRead: function(id) { return '_internal/notifications/read/' + id; },
        check: function(lastRequest) { return '_internal/notifications?last_request=' + lastRequest; }
    };

    var elements = {
        menu: [],
        newIndicator: [],
        noNewMessage: [],
        internalLink: [],
        externalLink: [],
        noLink: []
    };

    // Private Methods

    function initElements() {
        elements.menu = $('#new-notifications-menu');
        elements.newIndicator = elements.menu.find('.new-notifications-indicator');
        elements.noNewMessage = elements.menu.find('.no-notifications-messages');
        elements.internalLink = $('#tpl-notification-message-with-internal-link').remove().removeClass('hide').removeAttr('id');
        elements.externalLink = $('#tpl-notification-message-with-external-link').remove().removeClass('hide').removeAttr('id');
        elements.noLink = $('#tpl-notification-message-without-link').remove().removeClass('hide').removeAttr('id');

        bindNotificationLinks();
    }

    function initCronjob() {
        ifvisible.onEvery(options.cronjobInterval, checkForNewMessages);
    }

    function bindNotificationLinks() {
        elements.menu.find('.notification-message').unbind('click').click(function(e){
            if ($(this).hasClass('is-new')) {
                $(this).removeClass('is-new');
                $.ajax(urls.markRead($(this).data('id')));

                checkNewState();
            }
        });

        elements.menu.find('.notification-message a.internal').unbind('click').click(function(e){
            Parent.Overlay.load($(this).attr('href'), { size: $(this).data('size') || 'normal' });

            if ($(this).parent().hasClass('is-new')) {
                $(this).parent().removeClass('is-new');
                $.ajax(urls.markRead($(this).parent().data('id')));

                checkNewState();
            }

            return false;
        });

        Parent.Overlay.bindLinks();
    }

    function checkForNewMessages() {
        if (lastRequest + 30 > Math.floor(new Date().valueOf() / 1000)) {
            return;
        }

        $.getJSON(urls.check(lastRequest), function(data) {
            // To be absolutely correct, the request itself should give this timestamp
            lastRequest = Math.floor(new Date().valueOf() / 1000);

            if (data.length) {
                elements.noNewMessage.addClass('hide');
            }

            $.each(data, function(key, val) {
                var li;

                if ('' == val.link) {
                    li = elements.noLink.clone();
                } else if ('external' == val.size) {
                    li = elements.externalLink.clone();
                    li.find('a').attr('href', val.link);
                } else {
                    li = elements.internalLink.clone();
                    li.find('a').attr('href', val.link).data('size', val.size || 'normal');
                }

                li.data('id', val.id);
                li.find('span:not(.no-link)').text(val.text);

                if(window.Notification && Notification.permission !== "denied" && (lastRequest - val.createdAt) < 86400) {
                    Notification.requestPermission(function(status) {
                        var n = new Notification('RUNALYZE', {
                            body: val.text,
                            icon: '/favicon.ico',
                            timestamp: val.createdAt,
                        });
                        setTimeout(n.close.bind(n), 3500);
                    });
                }

                li.insertAfter(elements.noNewMessage);
            });

            checkNewState();
            bindNotificationLinks();
        });
    }

    function checkNewState() {
        var status = elements.menu.find('.notification-message.is-new').length == 0;

        elements.newIndicator.toggleClass('hide', status);
    }

    function clearMenu() {
        elements.menu.find('.notification-message').remove();
        elements.noNewMessage.removeClass('hide');
        elements.newIndicator.addClass('hide');
    }

    // Public Methods

    self.init = function() {
        initElements();
        initCronjob();
        checkNewState();
        checkForNewMessages(); // As long as base_logged_in.twig.html does not include current notifications
    };

    self.setLastRequestTime = function(timestamp) {
        lastRequest = timestamp;
    };

    self.bindToList = function(selector) {
        var $list = $(selector);
        var $new = $list.find('.is-new');

        if ($new.length) {
            $list.find('.is-new').unbind('click').click(function(e){
                var $el = $(this);

                $el.removeClass('is-new');
                $.ajax(urls.markRead($el.data('id')));

                elements.menu.find('.notification-message.is-new').filter(function(){
                    return $(this).data('id') === $el.data('id');
                }).remove();

                checkNewState();
            });

            $list.find('.internal').unbind('click').click(function(e){
                Parent.Overlay.load($(this).attr('href'), { size: $(this).data('size') || 'normal' });

                if ($(this).parent().hasClass('is-new')) {
                    var $el = $(this).parent();

                    $el.removeClass('is-new');
                    $.ajax(urls.markRead($el.data('id')));

                    elements.menu.find('.notification-message.is-new').filter(function(){
                        return $(this).data('id') === $el.data('id');
                    }).remove();

                    checkNewState();
                }

                return false;
            });

            $list.find('.read-all-notifications-link').unbind('click').click(function(e){
                e.preventDefault();

                $list.find('.is-new').removeClass('is-new');
                $.ajax(urls.markAllRead);
                $(this).parent().fadeOut();

                clearMenu();
            });
        } else {
            $list.find('.read-all-notifications-link').parent().remove();
        }
    };

    Parent.addInitHook('init-notifications', self.init);

    return self;
})(jQuery, Runalyze);

;
// ---- lib/runalyze.lib.sport.js ----
Runalyze.Sport = (function ($) {

    // Public

    var self = {};

    var zonebounds = null;
    var templateZone = null;
    var templateZoneId = null;
    var templateZoneName = null;

    function initHandlers() {
        zonebounds.find('.zonebound-add').click(function () {
            zonebounds.find('.bounds').append(templateZone);
            reBuildBounds();
        });

        copyBound = function () {
            var $p = $(this).parent();
            $p.clone().insertAfter($p);

            reBuildBounds();
        };
        removeBound = function () {
            $(this).parent().remove();
            reBuildBounds();
        };

        function reBuildBounds() {
            // reindex id and name for the symphony mapping of view/model
            var i = 0;
            zonebounds.find('li').each(function () {
                $(this).find('.zonebound-bpm input').attr('id', templateZoneId.replace(/__name__/g, i));
                $(this).find('.zonebound-bpm input').attr('name', templateZoneName.replace(/__name__/g, i++));
            })
            // re-register actions (so the new zones will be also triggered)
            zonebounds.find(".zonebound-copy").unbind('click').click(copyBound);
            zonebounds.find(".zonebound-remove").unbind('click').click(removeBound);
        }

        reBuildBounds();
    }

    self.init = function (elem) {
        zonebounds = $(elem.find('#hrZoneBounds'));

        // extract data from pototyp, backup id&name and then remove it
        var templateZoneProto = zonebounds.find('.bound-prototype');
        templateZone = '<li>' + templateZoneProto.html() + '</li>';
        templateZoneId = zonebounds.find('.bound-prototype input').attr('id');
        templateZoneName = zonebounds.find('.bound-prototype input').attr('name');
        templateZoneProto.remove();

        initHandlers();
    };

    return self;
})(jQuery);

