String.prototype.hashCode = function () {
    var text = "";
    var possible = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789";

    for (var i = 0; i < 15; i++)
        text += possible.charAt(Math.floor(Math.random() * possible.length));

    return text;
};

(function() {
    /* global d3 */
    d3.runalyzeplot = function(plotData) {
        var data = plotData,
            svg = [],
            id = [],
            height = 200,
            width = 690,
            margin = {
                top: 10,
                right: 10,
                bottom: 30,
                left: 50
            },
            plot = {
                gridArea: [],
                plotArea: [],
                axesArea: []
            },
            emptyFun = function() {};

        var self = {
            xValue: emptyFun, xScale: emptyFun, xMap: emptyFun, xAxis: emptyFun,
            yValue: emptyFun, yScale: emptyFun, yMap: emptyFun, yAxis: emptyFun
        };

        self.size = function(w, h) {
            if (!arguments.length) return [width, height];
            width = w - margin.left - margin.right;
            height = h;
            return self;
        };

        self.height = function(px) {
            if (!arguments.length) return height;
            height = px;
            return self;
        };

        self.width = function(px) {
            if (!arguments.length) return width;
            width = px - margin.left - margin.right;
            return self;
        };

        self.margin = function(def) {
            if (!arguments.length) return margin;
            margin = Object.assign(margin, def);
            return self;
        };

        self.select = function(selector) {
            id = selector.hashCode();
            svg = d3.select(selector).append("svg")
                .attr("width", width + margin.left + margin.right)
                .attr("height", height + margin.top + margin.bottom)
                .attr("class", "d3js")
                .append("g")
                .attr("transform", "translate(" + margin.left + "," + margin.top + ")");

            svg.append('clipPath').attr('id', 'clip-'+id).append('rect').attr('x', 0).attr('y',0).attr('width', width).attr('height', height);

            plot.gridArea = svg.append("g").attr('clip-path', 'url(#clip-'+id+')');
            plot.gridArea.append('rect').attr("class", "plot-area").attr('x', 0).attr('y', 0).attr('width', width).attr('height', height);
            plot.plotArea = svg.append("g").attr('clip-path', 'url(#clip-'+id+')');
            plot.axesArea = svg.append("g");

            self.xValue = self.xValue !== emptyFun ? self.xValue : function(d) { return d[0]; };
            self.xScale = self.xScale !== emptyFun ? self.xScale : d3.scaleLinear().range([0, width]).domain([d3.min(data, self.xValue), d3.max(data, self.xValue)]);
            self.xMap = self.xMap !== emptyFun ? self.xMap : function(d) { return self.xScale(self.xValue(d)); };
            self.xAxis = self.xAxis !== emptyFun ? self.xAxis : d3.axisBottom().scale(self.xScale);

            self.yValue = self.yValue !== emptyFun ? self.yValue : function(d) { return d[1]; };
            self.yScale = self.yScale !== emptyFun ? self.yScale : d3.scaleLinear().range([height, 0]).domain([d3.min(data, self.yValue), d3.max(data, self.yValue)]);
            self.yMap = self.yMap !== emptyFun ? self.yMap : function(d) { return self.yScale(self.yValue(d)); };
            self.yAxis = self.yAxis !== emptyFun ? self.yAxis : d3.axisLeft().scale(self.yScale);

            return self;
        };

        self.svg = function() {
            return svg;
        };

        self.gridArea = function() {
            return plot.gridArea;
        };

        self.plotArea = function() {
            return plot.plotArea;
        };

        self.axesArea = function() {
            return plot.axesArea;
        };

        self.drawAxes = function() {
            plot.yAxis = plot.axesArea.append("g")
                .attr("class", "y axis")
                .call(self.yAxis);

            plot.xAxis = plot.axesArea.append("g")
                .attr("class", "x axis")
                .attr("transform", "translate(0," + height + ")")
                .call(self.xAxis);
        };

        self.drawXGrid = function(ticks) {
            ticks = ticks || self.xScale.ticks().length;

            plot.gridArea.selectAll("line.grid.x").data(self.xScale.ticks(ticks)).enter()
                .append("line")
                .attr("class", "grid")
                .attr("x1", function(d){ return self.xScale(d) + 0.5; })
                .attr("x2", function(d){ return self.xScale(d) + 0.5; })
                .attr("y1", 0)
                .attr("y2", height);
        };

        self.drawYGrid = function(ticks) {
            ticks = ticks || self.yScale.ticks().length;

            plot.gridArea.selectAll("line.grid.y").data(self.yScale.ticks(ticks)).enter()
                .append("line")
                .attr("class", "grid")
                .attr("y1", function(d){ return self.yScale(d) + 0.5; })
                .attr("y2", function(d){ return self.yScale(d) + 0.5; })
                .attr("x1", 0)
                .attr("x2", width);
        };

        self.drawLine = function(d, c, interpolation) {
            d = d || data;
            c = c || "";
            interpolation = interpolation || d3.curveBasis;

            return plot.plotArea.append("path")
                .datum(d)
                .attr("class", "line "+ c)
                .attr("d", d3.line()
                    .x(self.xMap)
                    .y(self.yMap)
                    .curve(interpolation)
                )
            ;
        };

        self.drawArea = function(d, c) {
            d = d || data;
            c = c || "";

            return [
                plot.plotArea.append("path")
                    .datum(d)
                    .attr("class", "area "+ c)
                    .attr("d", d3.area().x(self.xMap).y0(height).y1(self.yMap)),
                plot.plotArea.append("path")
                    .attr("class", c)
                    .attr("d", d3.line().x(self.xMap).y(self.yMap)(d))
            ];
        };

        self.drawCircles = function(d, c, r) {
            d = d || data;
            c = c || "";
            r = r || 3.5;

            return plot.plotArea.append("g").attr("class", c).selectAll("circle")
                .data(d)
                .enter().append("circle")
                .attr("r", r)
                .attr("cx", self.xMap)
                .attr("cy", self.yMap);
        };

        return self;
    };
})();

;
// ---- assets/js/d3js-boxplot.js ----
(function() {
    d3.functor = function functor(v) {
        return typeof v === "function" ? v : function() {
                return v;
            };
    };

    d3.boxplot = function() {
        var height = 1,
            domain = null,
            whiskers = boxWhiskers,
            quartiles = boxQuartiles,
            tooltip = null,
            xAxis = null;

        function box(g) {
            g.each(function(data, i) {
                if (data[1].length == 0) return;

                var d = data[1].sort(d3.ascending);
                var g = d3.select(this);
                var n = d.length;
                var quartileData = d.quartiles = quartiles(d);
                var whiskerIndices = whiskers && whiskers.call(this, d, i);
                var whiskerData = whiskerIndices && whiskerIndices.map(function(i) { return d[i]; });
                var outlierIndices = whiskerIndices
                    ? d3.range(0, whiskerIndices[0]).concat(d3.range(whiskerIndices[1] + 1, n))
                    : d3.range(n);

                g.selectAll("line.center")
                    .data(whiskerData ? [whiskerData] : [])
                    .enter().insert("line", "rect")
                    .attr("class", "center")
                    .attr("y1", height / 2)
                    .attr("y2", height / 2)
                    .attr("x1", function(d) { return xAxis(d[0]); })
                    .attr("x2", function(d) { return xAxis(d[1]); });

                var rect = g.selectAll("rect.box")
                    .data([quartileData])
                    .enter().append("rect")
                    .attr("class", "box")
                    .attr("y", 0)
                    .attr("height", height)
                    .attr("x", function(d) { return Math.min(xAxis(d[0]), xAxis(d[2])); })
                    .attr("width", function(d) { return Math.abs(xAxis(d[2]) - xAxis(d[0])); });

                if (tooltip) {
                    rect.on('mouseover', tooltip.show)
                        .on('mouseout', tooltip.hide);
                }

                g.selectAll("line.median")
                    .data([quartileData[1]])
                    .enter().append("line")
                    .attr("class", "median")
                    .attr("y1", 0)
                    .attr("y2", height)
                    .attr("x1", xAxis)
                    .attr("x2", xAxis);

                g.selectAll("line.whisker")
                    .data(whiskerData || [])
                    .enter().insert("line", "circle, text")
                    .attr("class", "whisker")
                    .attr("y1", 0)
                    .attr("y2", height)
                    .attr("x1", xAxis)
                    .attr("x2", xAxis);

                g.selectAll("circle.outlier")
                    .data(outlierIndices, Number)
                    .enter().insert("circle", "text")
                    .attr("class", "outlier")
                    .attr("r", 2)
                    .attr("cy", height / 2)
                    .attr("cx", function(i) { return xAxis(d[i]); });
            });

            d3.timerFlush();
        }

        box.height = function(x) {
            if (!arguments.length) return height;
            height = x;
            return box;
        };

        box.tooltip = function(x) {
            if (!arguments.length) return tooltip;
            tooltip = x;
            return box;
        };

        box.xAxis = function(x) {
            if (!arguments.length) return xAxis;
            xAxis = x;
            return box;
        };

        box.domain = function(x) {
            if (!arguments.length) return domain;
            domain = x == null ? x : d3.functor(x);
            return box;
        };

        box.whiskers = function(x) {
            if (!arguments.length) return whiskers;
            whiskers = x;
            return box;
        };

        return box;
    };

    function boxWhiskers(d) {
        return [0, d.length - 1];
    }

    function boxQuartiles(d) {
        return [
            d3.quantile(d, .25),
            d3.quantile(d, .5),
            d3.quantile(d, .75)
        ];
    }
})();

;
// ---- assets/js/climb-score.js ----

var DouglasPeucker = function (points, epsilon) {
    /*
     * Based on code by Marius Karthaus, www.lowvoice.nl
     * @see https://karthaus.nl/rdp/js/rdp2.js
     */
    function RDPsd(points, epsilon) {
        var firstPoint = points[0];
        var lastPoint = points[points.length - 1];

        if (points.length < 3){
            return points;
        }

        var index = -1;
        var dist = 0;

        for (var i = 1; i < points.length - 1; i++){
            var cDist = distanceFromPointToLine(points[i], firstPoint, lastPoint);

            if (cDist > dist){
                dist = cDist;
                index = i;
            }
        }

        if (dist > epsilon) {
            var l1 = points.slice(0, index + 1);
            var l2 = points.slice(index);
            var r1 = RDPsd(l1, epsilon);
            var r2 = RDPsd(l2, epsilon);

            return r1.slice(0, r1.length - 1).concat(r2);
        } else {
            return [firstPoint, lastPoint];
        }
    }


    var distanceFromPointToLine = function (p, a, b){
        return Math.sqrt(distanceFromPointToLineSquared(
            {x: p[0], y: p[1]},
            {x: a[0], y: a[1]},
            {x: b[0], y: b[1]}
        ));
    };

    var distanceFromPointToLineSquared = function (p, i, j) {
        var lineLength = pointDistance(i, j);

        if (lineLength == 0) {
            return pointDistance(p, i);
        }

        var t = ((p.x - i.x) * (j.x - i.x) + (p.y - i.y) * (j.y - i.y)) / lineLength;

        if (t < 0) {
            return pointDistance(p, i);
        } else if (t > 1) {
            return pointDistance(p, j);
        }

        return pointDistance(p, {
            x: i.x + t * (j.x - i.x),
            y: i.y + t * (j.y - i.y)
        });
    };

    var pointDistance = function (i, j){
        return (i.x - j.x) * (i.x - j.x) + (i.y - j.y) * (i.y - j.y);
    };

    return RDPsd(points, epsilon);
};

var ClimbScore = (function ($) {
    /**
     * @param array data [[distance_1, elevation_1], ...]
     * @param float epsilon parameter for douglas-peucker, default 1.1
     */
    return function (data, epsilon) {
        if (typeof epsilon === "undefined") {
            epsilon = 1.1;
        }

        var result = {
            reducedProfile:     [],
            gradientProfile:    [],
            gradientHistogram:  [],
            climbs:             [],
            totalScore:         0.0,
            percentageFlat:     0.0,
            percentageHilly:    0.0
        };

        var distance = data.map(function(d) { return d[0]; });

        result.reducedProfile = DouglasPeucker(data, epsilon);
        result.gradientProfile = getGradientProfile(data, 0.2, 0.0);
        result.gradientHistogram = getGradientHistogram(result.gradientProfile);

        var sumUpFlatDown = countUpFlatDown(result.gradientHistogram);
        var sumTotal = sumUpFlatDown[0] + sumUpFlatDown[1] + sumUpFlatDown[2];

        result.percentageHilly = 100.0 * (sumUpFlatDown[0] + sumUpFlatDown[2]) / sumTotal;
        result.percentageFlat = 100.0 * (sumUpFlatDown[1]) / sumTotal;

        var totalScore = 0.0;
        var totalScoreLog = 0.0;
        var totalScoreAvg = 0.0;
        var totalScoreAvg2 = 1.0;
        var totalDist = result.reducedProfile[result.reducedProfile.length - 1][0] - result.reducedProfile[0][0];

        for (var i = 1; i < result.reducedProfile.length; ++i) {
            var dist = result.reducedProfile[i][0] - result.reducedProfile[i - 1][0];
            var vm = result.reducedProfile[i][1] - result.reducedProfile[i - 1][1];
            var gradient = 100 * (vm / 1000) / dist;

            if (vm > 0 && dist > 0.1) {
                var indexStart = d3.bisect(distance, result.reducedProfile[i - 1][0]) - 1;
                var indexEnd = d3.bisect(distance, result.reducedProfile[i][0]) - 1;

                var categoryFiets = false;
                var climbProfile = getGradientProfile(data.slice(indexStart, indexEnd + 1), 0.1, result.reducedProfile[i - 1][0]);
                var scores = calculateScores(result.reducedProfile[i - 1], result.reducedProfile[i], climbProfile);
                var fiets = scores[0];

                totalScore = totalScore + fiets;
                totalScoreLog = totalScoreLog + Math.log(1.0 + fiets);
                totalScoreAvg = totalScoreAvg + fiets / Math.pow(Math.max(1.0, totalDist / 10), 0.75) / 10;

                if (gradient >= 2.0) {
                    totalScoreAvg2 = totalScoreAvg2 + fiets / Math.max(1.0, Math.sqrt(totalDist / 20));
                }

                if (fiets >= 6.5) {
                    categoryFiets = 'hc';
                } else if (fiets >= 5.0) {
                    categoryFiets = '1';
                } else if (fiets >= 3.5) {
                    categoryFiets = '2';
                } else if (fiets >= 2.0) {
                    categoryFiets = '3';
                } else if (fiets >= 0.5) {
                    categoryFiets = '4';
                } else if (fiets >= 0.25) {
                    categoryFiets = '5';
                }

                if (categoryFiets !== false) {
                    result.climbs.push({
                        indexStart: indexStart,
                        indexEnd: indexEnd,
                        reducedStartIndex: i - 1,
                        distanceStart: result.reducedProfile[i - 1][0],
                        elevation: vm,
                        altitudeTop: result.reducedProfile[i][1],
                        distance: dist,
                        gradient: gradient,
                        category: categoryFiets,
                        scoreFietsSum: scores[0],
                        scoreFiets: scores[1],
                        scoreCbb: scores[2],
                        scoreSalite: scores[3],
                        scoreCodifava: scores[4]
                    });
                }
            }
        }

        var flatCompensation = 1 - result.percentageFlat * result.percentageFlat / 10000;

        result.totalScore = {
            sum: Math.min(10.0, Math.max(0.0, 2.0 * Math.log(totalScore * flatCompensation))),
            weightedSum: Math.min(10.0, Math.max(0.0, 2.0 * Math.log2(1.0 + totalScoreAvg * flatCompensation))),
            weightedSumClimbs: Math.min(10.0, Math.max(0.0, 2.0 * Math.log2(0.5 + totalScoreAvg2 * flatCompensation)))
        };

        function getGradientProfile(data, threshold, firstDistance) {
            var lastIndex = 0;
            var currentIndex = 1;
            var g = [[firstDistance, 0]];

            while (currentIndex < data.length) {
                if (data[currentIndex][0] - data[lastIndex][0] >= threshold) {
                    g.push([data[currentIndex][0], 100 * (data[currentIndex][1] - data[lastIndex][1]) / (data[currentIndex][0] - data[lastIndex][0]) / 1000]);
                    lastIndex = currentIndex;
                }

                currentIndex++;
            }

            if (currentIndex > lastIndex + 1 && data[currentIndex - 1][0] - data[lastIndex][0] > 0.0) {
                g.push([data[currentIndex - 1][0], 100 * (data[currentIndex - 1][1] - data[lastIndex][1]) / (data[currentIndex - 1][0] - data[lastIndex][0]) / 1000]);
            }

            return g;
        }

        function countUpFlatDown(hist) {
            var up = 0.0;
            var flat = 0.0;
            var down = 0.0;

            for (var histClass in hist) {
                if (histClass >= 2.0) {
                    up += hist[histClass];
                } else if (histClass < -2.0) {
                    down += hist[histClass];
                } else {
                    flat += hist[histClass];
                }
            }

            return [up, flat, down];
        }

        function getGradientHistogram(gradient) {
            var hist = [];
            var histClass = 0;
            var dist = 0;

            for (var i = 1; i < gradient.length; ++i) {
                histClass = (Math.floor(gradient[i][1])).toString();
                dist = gradient[i][0] - gradient[i - 1][0];

                if (histClass in hist) {
                    hist[histClass] += dist;
                } else {
                    hist[histClass] = dist;
                }
            }

            return hist;
        }

        function calculateScores(pointFrom, pointTo, climbProfile) {
            var d = pointTo[0] - pointFrom[0]; // [km]
            var h = pointTo[1] - pointFrom[1]; // [m]
            var t = pointTo[1]; // [m]
            var g = h / d / 10; // [%]

            var fiets = h * h / (d * 10000) + Math.max(0, (t - 1000) / 1000);
            var cbb = 2 * g + h * h / (1000 * d) + d + Math.max(0, (t - 1000) / 100);
            var salite = g * g * d; // Should be a sum for all segments, now it's approx. 100*fiets
            var codifava = (h + 400) / (10 * h) * (g * g * d / 10); // Last part should be a sum

            var fietsSum = 0.0;
            for (var i = 1; i < climbProfile.length; ++i) {
                if (climbProfile[i][1] > 0) {
                    fietsSum += Math.pow(Math.min(25, climbProfile[i][1]), 2) * (climbProfile[i][0] - climbProfile[i - 1][0]) / 100;
                }
            }

            fiets = Math.min(1.5 * h * h / (d * 10000), fiets);
            fietsSum = Math.min(1.5 * fietsSum, fietsSum + Math.max(0, (t - 1000) / 1000));

            return [fietsSum, fiets, cbb, salite, codifava];
        }

        return result;
    }
})(jQuery);

